import 'package:dio/dio.dart'; import 'dart:convert'; void main() async { try { var res = await Dio().get('https://api-v2.soundcloud.com/search/tracks?q=Pineapple%20Express%20Fineapple&client_id=Pb72ranhoyt6gw7hM7TkzUItXlMWSNSo&limit=10'); var data = res.data is String ? jsonDecode(res.data) : res.data; var tracks = data['collection'] as List<dynamic>; for (var t in tracks) { print(t['title'] + ' by ' + t['user']['username']); } } catch (e) { print(e); } }
